import {Run,ROUTES} from './engine.js?v=3';
import {Art} from './art.js?v=3';
import {GentleMusic} from './music.js?v=3';
const $=id=>document.getElementById(id);
let run=new Run(3),art=new Art(),scene,accumulator=0,soundOn=false,audio,toastTimer,modalAction,secondaryAction;
const music=new GentleMusic({onStatus:status=>{const labels={ready:'点击出发后播放',playing:'正在播放 · 海风慢拍',paused:'已暂停 · 随游戏继续',off:'轻音乐已关闭',unavailable:'暂时无法播放，请点击音乐键重试'};$('music-status').textContent=labels[status];}});
try{const prefs=JSON.parse(localStorage.getItem('sunset-music')||'{}');if(typeof prefs.enabled==='boolean')music.setEnabled(prefs.enabled);if(Number.isFinite(prefs.volume))music.setVolume(prefs.volume);}catch{}
function musicUI(){$('music').setAttribute('aria-pressed',String(music.enabled));$('music').setAttribute('aria-label',music.enabled?'关闭背景轻音乐':'开启背景轻音乐');$('music-toggle').setAttribute('aria-pressed',String(music.enabled));$('music-toggle').textContent=music.enabled?'♫ 轻音乐 · 开':'♫ 轻音乐 · 关';$('music-volume').value=Math.round(music.volume*100);}
function saveMusic(){try{localStorage.setItem('sunset-music',JSON.stringify({enabled:music.enabled,volume:music.volume}));}catch{}}
function toggleMusic(){music.setEnabled(!music.enabled);if(music.enabled)music.play();musicUI();saveMusic();$('music').blur();$('music-toggle').blur();}
$('music').onclick=toggleMusic;$('music-toggle').onclick=toggleMusic;$('music-volume').oninput=e=>{music.setVolume(Number(e.target.value)/100);saveMusic();};musicUI();
let records={};try{const saved=JSON.parse(localStorage.getItem('sunset-skate-v2')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))records=saved;}catch{}
function saveRecord(){const old=records[run.level.index];records[run.level.index]={stars:Math.max(Number(old?.stars)||0,run.collected.size),score:Math.max(Number(old?.score)||0,run.score),completed:true};try{localStorage.setItem('sunset-skate-v2',JSON.stringify(records));}catch{}updateRecord();}
function updateRecord(){const r=records[run.level.index];$('best').textContent=r?.completed?`个人最佳 · ${Number(r.score)||0} 分 · ${Number(r.stars)||0} 星`:'个人最佳 · 等你创造';document.querySelectorAll('.route-record').forEach((e,i)=>e.textContent=records[i]?.completed?'✓ 已完成':'');}
function sound(type){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const tones={jump:[250,500,.12],star:[780,1200,.12],land:[110,60,.07],crash:[190,45,.28],checkpoint:[600,900,.24],win:[500,1400,.6],grind:[180,700,.25]};const [a,b,d]=tones[type]||tones.star;const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type==='crash'?'sawtooth':'sine';osc.frequency.setValueAtTime(a,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(b,audio.currentTime+d);gain.gain.setValueAtTime(.07,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+d);}catch{}}
function toast(message,duration=2200){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),duration);}
function updateHud(){
 $('stars').textContent=String(run.collected.size).padStart(2,'0');$('distance').textContent=Math.floor(run.progress*run.level.length/10);$('progress-fill').style.width=`${run.progress*100}%`;$('charge-fill').style.width=`${run.charge*100}%`;
 $('charge-label').textContent=run.grinding?'滑杆中 · 可再次起跳':run.sliding?'压低身体 · 通过再松手':run.holding?(run.charge>=1?'蓄力满了，松开！':'蓄力中… 松开起跳'):'轻点小跳 · 长按蓄力';$('jump').classList.toggle('charging',run.holding);$('slide').classList.toggle('active',run.duckHeld);
 const playing=run.state==='playing',next=run.nextAction;$('game-shell').classList.toggle('playing',playing);$('flow').hidden=!playing;$('combo').textContent=`× ${run.combo}`;$('score').textContent=`${run.score.toLocaleString()} 分`;$('action-cue').hidden=!playing||!next;
 if(next){const labels={jump:['↑','跳过路障','空格 / 跳跃'],gap:['↗','前方断崖','提前蓄力，再松开'],slide:['↓','低头滑过去','按住 ↓ / S / 滑行'],rail:['↗','跳上栏杆','从上方落下，自动滑杆'],grinding:['✦','滑杆中！','滑到底加分 · 可再次起跳'],transfer:['↗','杆尾前，再跳一次！','长按蓄力，接到下一根杆']};const [icon,title,detail]=labels[next.kind];$('cue-icon').textContent=icon;$('cue-title').textContent=title;$('cue-detail').textContent=next.distance>0?`${next.distance} m · ${detail}`:detail;$('action-cue').dataset.kind=next.kind;}
}
function hideModal(){$('modal').hidden=true;}
function showModal({eyebrow,title,copy,primary,secondary,action,second,stats=false}){run.cancelInput();$('modal-eyebrow').textContent=eyebrow;$('modal-title').textContent=title;$('modal-copy').textContent=copy;$('modal-primary').textContent=primary;$('modal-secondary').textContent=secondary;modalAction=action;secondaryAction=second;$('result-stats').hidden=!stats;if(stats)$('result-stats').innerHTML=`<div><b>${run.score.toLocaleString()}</b><span>动作总分</span></div><div><b>${run.collected.size}</b><span>收集星星</span></div><div><b>${Math.round(run.grindDistance/10)}m</b><span>滑杆距离</span></div>`;$('modal').hidden=false;$('play-controls').hidden=true;$('pause').disabled=true;requestAnimationFrame(()=>$('modal-primary').focus({preventScroll:true}));}
function start(){music.play();hideModal();run.reset();run.start();art=new Art();art.camera=0;accumulator=0;$('cover').hidden=true;$('play-controls').hidden=false;$('pause').disabled=false;$('start').blur();toast('空格跳跃 · ↓ / S 低头滑行 · 看左上角提示',3500);updateHud();}
function retry(){music.play();run.retry();art.camera=Math.max(0,run.x-200);art.particles=[];accumulator=0;hideModal();$('play-controls').hidden=false;$('pause').disabled=false;toast(run.checkpoint.x>160?'从检查点出发 · 再来一次':'慢慢来，起跳前留一点距离');$('modal-primary').blur();}
function resume(){music.play();hideModal();run.resume();accumulator=0;$('play-controls').hidden=false;$('pause').disabled=false;$('pause').textContent='Ⅱ';$('modal-primary').blur();}
function pause(){if(run.state==='paused'){resume();return;}if(run.state!=='playing')return;run.pause();music.pause();showModal({eyebrow:'TAKE A BREATHER',title:'风景值得慢一点。',copy:'你的滑板就在这里，准备好再出发。',primary:'继续滑行 →',secondary:'重新开始这条路线',action:resume,second:start});}
function selectRoute(index){run=new Run(index);art=new Art();accumulator=0;hideModal();$('cover').hidden=false;$('play-controls').hidden=true;$('pause').disabled=true;$('route-index').textContent=String(index+1).padStart(2,'0');$('route-name').textContent=ROUTES[index].name;$('route-sub').textContent=ROUTES[index].en;$('game-shell').classList.toggle('night-scene',index===2||ROUTES[index].night===true);document.querySelectorAll('.route-card').forEach((e,i)=>{e.classList.toggle('selected',i===index);e.setAttribute('aria-pressed',i===index?'true':'false');});$('toast').classList.remove('show');$('cover-title').innerHTML=run.level.hard?'这次，<br>玩点狠的。':'下一站，<br>海边。';$('cover-label').textContent=run.level.hard?`${run.level.tag} / ${run.level.en}`:'JUMP · SLIDE · GRIND';$('cover-description').textContent=run.level.description||'跳过去，滑过去，玩出你的路线。';$('start').innerHTML=run.level.hard?'挑战这条路线 <span>↗</span>':'出发，追日落 <span>↗</span>';document.querySelectorAll('.progress-marker').forEach(e=>e.remove());for(const cp of run.level.checkpoints){const marker=document.createElement('span');marker.className='progress-marker';marker.style.left=`${(cp-160)/(run.level.length-160)*100}%`;document.querySelector('.route-progress').append(marker);}updateHud();updateRecord();}
function handleEvents(){for(const e of run.events.splice(0)){if(e.type!=='clear')sound(e.type);if(e.type==='grind')toast('✦ 成功上杆！滑过箱阵，滑到底额外加分',1800);if(e.type==='clear'&&e.kind==='grind')toast(`漂亮！滑杆完成 +${e.points} 分`,1500);if(e.type==='star')art.burst(e.x,e.y,'#ffe49a',8);if(e.type==='land')art.burst(run.x,run.y,'#d2c596',5);if(e.type==='checkpoint')toast('✓ 检查点已保存 · 放心向前');if(e.type==='crash'){art.burst(run.x,run.y-20,'#f1bf7e',16);showModal({eyebrow:'FALL. GET UP. ROLL AGAIN.',title:'没关系，再来一次。',copy:run.crashReason,primary:run.checkpoint.x>160?'从检查点继续 ↗':'再试一次 ↗',secondary:'重新开始这条路线',action:retry,second:start});}if(e.type==='win'){saveRecord();showModal({eyebrow:'YOU CAUGHT THE SUNSET',title:'这一程，漂亮！',copy:run.level.index===ROUTES.length-1?'从落日到蓝调，海岸线已经留下你的轮印。':'海风记住了你的名字。下一段风景，继续一起。',primary:run.level.index<ROUTES.length-1?'出发，下一条路线 ↗':'再滑一次 ↗',secondary:'重玩这条路线',action:()=>{if(run.level.index<ROUTES.length-1){selectRoute(run.level.index+1);start();}else start();},second:start,stats:true});}}
}
class CoastScene extends (window.Phaser?.Scene || class {}){
 constructor(){super('coast');}
 create(){scene=this;this.tex=this.textures.createCanvas('world',this.scale.width,this.scale.height);this.img=this.add.image(0,0,'world').setOrigin(0);this.scale.on('resize',size=>{this.tex.setSize(size.width,size.height);this.img.setDisplaySize(size.width,size.height);});this.input.keyboard.addCapture(['SPACE','UP','DOWN']);this.input.keyboard.on('keydown',event=>{const code=({p:'KeyP',P:'KeyP',r:'KeyR',R:'KeyR',s:'KeyS',S:'KeyS',' ':'Space',ArrowUp:'ArrowUp',ArrowDown:'ArrowDown',Escape:'Escape'})[event.key]||event.code;if($('help').open||event.repeat)return;if(['KeyP','Escape'].includes(code)){event.preventDefault();pause();return;}if(code==='KeyR'&&run.state!=='ready'){event.preventDefault();start();return;}const interactive=event.target instanceof HTMLElement&&event.target.closest('button,a,input,select,textarea');if(interactive)return;if(['ArrowDown','KeyS'].includes(code)){event.preventDefault();run.setDuck(true);}if(['Space','ArrowUp'].includes(code)){event.preventDefault();if(run.state==='ready'){start();return;}if(run.state==='playing')run.press();}});this.input.keyboard.on('keyup',event=>{const code=({s:'KeyS',S:'KeyS',' ':'Space',ArrowUp:'ArrowUp',ArrowDown:'ArrowDown'})[event.key]||event.code;if(['Space','ArrowUp'].includes(code))run.release();if(['ArrowDown','KeyS'].includes(code))run.setDuck(false);});this.input.on('pointerdown',()=>{if(run.state==='playing')run.press();});this.input.on('pointerup',()=>run.release());this.input.on('pointerupoutside',()=>run.release());this.game.events.on('blur',()=>{if(run.state==='playing')pause();});updateRecord();}
 update(time,delta){const dt=Math.min(delta/1000,.05);if(run.state==='playing'){accumulator+=dt;while(accumulator>=1/120){run.step(1/120);accumulator-=1/120;}}else accumulator=0;handleEvents();art.draw(this.tex.context,this.scale.width,this.scale.height,run,run.state==='paused'?0:dt,run.state==='ready');this.tex.refresh();updateHud();}
}
$('start').onclick=start;$('pause').onclick=pause;$('modal-primary').onclick=()=>modalAction?.();$('modal-secondary').onclick=()=>secondaryAction?.();
$('sound').onclick=()=>{soundOn=!soundOn;$('sound').setAttribute('aria-pressed',String(soundOn));$('sound').setAttribute('aria-label',soundOn?'关闭音效':'开启音效');$('sound').title=soundOn?'关闭音效':'开启音效';sound('star');$('sound').blur();};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('game-shell').requestFullscreen)await $('game-shell').requestFullscreen();else toast('当前浏览器不支持全屏，可横屏游玩');}catch{toast('暂时无法全屏，可直接在这里游玩');}$('fullscreen').blur();};
$('jump').addEventListener('pointerdown',e=>{e.preventDefault();$('jump').setPointerCapture(e.pointerId);run.press();});$('jump').addEventListener('pointerup',e=>{e.preventDefault();run.release();});$('jump').addEventListener('pointercancel',()=>run.cancelJump());$('jump').addEventListener('lostpointercapture',()=>run.cancelJump());$('jump').addEventListener('contextmenu',e=>e.preventDefault());
$('jump').addEventListener('keydown',e=>{if(['Space','Enter'].includes(e.code)){e.preventDefault();if(!e.repeat)run.press();}});$('jump').addEventListener('keyup',e=>{if(['Space','Enter'].includes(e.code)){e.preventDefault();run.release();}});
$('slide').addEventListener('pointerdown',e=>{e.preventDefault();$('slide').setPointerCapture(e.pointerId);run.setDuck(true);});
for(const event of ['pointerup','pointercancel','lostpointercapture'])$('slide').addEventListener(event,()=>run.setDuck(false));
$('slide').addEventListener('contextmenu',e=>e.preventDefault());
$('slide').addEventListener('keydown',e=>{if(['Space','Enter'].includes(e.code)){e.preventDefault();run.setDuck(true);}});$('slide').addEventListener('keyup',e=>{if(['Space','Enter'].includes(e.code)){e.preventDefault();run.setDuck(false);}});
for(let i=3;i<ROUTES.length;i++){const r=ROUTES[i],button=document.createElement('button');button.className='route-card hard-card';button.dataset.route=i;button.setAttribute('aria-pressed','false');button.innerHTML=`<div class="route-art challenge-art" style="--sky:${r.sky[0]};--ridge:${r.hill}"><span class="mini-sun"></span><span class="mini-mountains"></span><span class="route-number">${String(i+1).padStart(2,'0')}</span><span class="new-tag">NEW</span></div><div class="route-detail"><span class="route-tag">${r.tag}</span><h3>${r.name} <span>↗</span></h3><p>${r.description}</p><div><span>${(r.length/10).toLocaleString()} m</span><span class="difficulty">${i===7?'★★★★★':'★'.repeat(i-1)}</span><span class="route-record"></span></div></div>`;$('challenge-routes').append(button);}
document.querySelectorAll('.route-card').forEach(e=>e.onclick=()=>{selectRoute(Number(e.dataset.route));$('game-shell').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'center'});e.blur();});
$('help-open').onclick=()=>{if(run.state==='playing')pause();$('help').showModal();};$('help-close').onclick=()=>$('help').close();$('help').addEventListener('click',e=>{if(e.target===$('help')){const r=$('help').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('help').close();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){music.pause();if(run.state==='playing')pause();}else if(run.state==='playing')music.play();});window.addEventListener('pagehide',()=>music.pause());
selectRoute(3);
if(!window.Phaser){$('start').textContent='引擎未加载，请刷新重试';$('start').disabled=true;}else new Phaser.Game({type:Phaser.CANVAS,parent:'game',backgroundColor:'#f7ce9c',banner:false,audio:{noAudio:true},scale:{mode:Phaser.Scale.RESIZE,width:$('game').clientWidth,height:$('game').clientHeight},scene:CoastScene,disableContextMenu:true,fps:{target:60,limit:60},input:{activePointers:2}});
